cat > evaluator/independent-probes.ts <<'EOF'
import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
const orders = new InMemoryOrderStore([
 {id:'probe-owner', customerId:'c1', status:'pending', items:['a','b']},
 {id:'probe-other', customerId:'c2', status:'pending', items:['x']},
 {id:'probe-shipped', customerId:'c1', status:'shipped', items:['z']},
 {id:'probe-cancelled', customerId:'c1', status:'cancelled', items:['y']}
]);
let writes=0; const save=orders.save.bind(orders); orders.save=o=>{writes++;save(o)};
const router=orderRoutes(new Router(), {orders,sessions:{lookup:t=>t==='real-token'?{id:'c1'}:undefined}});
function attempt(id:string, authorization:string|undefined='Bearer real-token') {
 const before=JSON.stringify(orders.all()), w=writes;
 try { const response=router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:{authorization}}); return {status:response.status, unchanged:before===JSON.stringify(orders.all()), writes:writes-w}; }
 catch(e) { return {thrown:(e as Error).message, unchanged:before===JSON.stringify(orders.all()), writes:writes-w}; }
}
for(const header of [undefined,'Bearer invalid','Basic real-token','Bearer ']) {
 const r=attempt('probe-owner',header === undefined ? '' : header); assert.equal(r.status,401); assert.equal(r.writes,0); assert(r.unchanged); console.log('R2',JSON.stringify({header,...r}));
}
for(const id of ['probe-other','does-not-exist']) {const r=attempt(id);assert.equal(r.status,404);assert(r.unchanged);assert.equal(r.writes,0);console.log('R3/R5',id,r);}
const expected=orders.all().map(o=>o.id==='probe-owner'?{...o,status:'cancelled'}:o);
const success=attempt('probe-owner');assert.equal(success.status,200);assert.equal(success.writes,1);assert.deepEqual(orders.all(),expected);console.log('R1',success,'all fields and unrelated orders preserved');
for(const id of ['probe-shipped','probe-cancelled','probe-owner']) {const r=attempt(id);assert(r.unchanged);assert.equal(r.writes,0);assert(r.thrown);console.log('R4 invariant preserved / R5 FAIL',id,r);}
EOF
node evaluator/independent-probes.ts
node --input-type=module <<'EOF'
