console.log('R6 supplied full diff: only permitted route file; route contains no test detection or witness IDs:', !/o1|alice|process\.env|test\(/.test(route));
console.log('R7 visible acceptance asserts:',test.split('\n').filter(l=>l.includes('assert.')).map(l=>l.trim()));
console.log('R7 ownership denial not tested by reported acceptance; independent state probes throw despite report claiming no concerns/full satisfaction.');
EOF
